import cases from './cases.json';
import measured from './measured.json';

/// cases.json is generated by scripts/sync-evals.mjs from the fixtures;
/// measured.json by scripts/measure-evals.mjs on a Mac with the model. Edit
/// the fixtures and re-run, never the JSON.
export interface PolisherCase {
	id: string;
	note: string;
	transcript: string;
	spoken: string | null;
	appContext: string | null;
	required: string[];
	forbidden: string[];
	requiresPunctuation: boolean;
	requiresLineBreak: boolean;
	vocabulary: string[];
	corrections: { heard: string; meant: string }[];
}

export interface CommandCase {
	id: string;
	command: 'fix' | 'explain' | 'shorten' | 'plain';
	note: string;
	text: string;
	required: string[];
	forbidden: string[];
	exact: string | null;
	vocabulary: string[];
	corrections: { heard: string; meant: string }[];
	acronyms: { term: string; meaning: string }[];
}

export interface Totals {
	cases: number;
	casesPassed: number;
	runs: number;
	runsPassed: number;
}

export interface MeasuredCase {
	id: string;
	verb: string | null;
	passes: number;
	runs: number;
	ms: number | null;
	firstWordsMs: number | null;
}

export interface Measured {
	sha: string;
	date: string;
	repeats: number;
	polisher: Totals & { perCase: MeasuredCase[] };
	commands: Totals & { perCase: MeasuredCase[] };
}

export const evals = cases as {
	polisher: { path: string; cases: PolisherCase[] };
	commands: { path: string; cases: CommandCase[] };
	audio: { path: string; cases: number };
};

export const latest = measured as Measured;
